     2665:         return 1;
     2666:     }
     2667:     m = (uint32_t *)_TIFFmallocExt(tif, count * 2 * sizeof(uint32_t));
     2668:     if (m == NULL)
     2669:     {
     2670:         TIFFErrorExtR(tif, module, "Out of memory");
     2671:         return (0);
     2672:     }
